    private function enqueue_calendar_script() {
        if ( wp_script_is( 'wcai-product-booking-calendar', 'enqueued' ) ) {
            return;
        }

        wp_register_script( 'wcai-product-booking-calendar', false, array(), WCAI_VERSION, true );
        wp_enqueue_script( 'wcai-product-booking-calendar' );

        wp_add_inline_script(
            'wcai-product-booking-calendar',
            'window.wcaiBookingI18n = ' . wp_json_encode(
                array(
                    'cartHint'   => __( 'Escolha data e horário', 'wooadventure-integration' ),
                    'fetchError' => __( 'Não foi possível atualizar a disponibilidade. Mostrando os últimos dados carregados; tente novamente.', 'wooadventure-integration' ),
                    'timesCount' => __( '%d horário(s) disponível(is) em %s', 'wooadventure-integration' ),
                    'selected'   => __( 'Selecionado: %s', 'wooadventure-integration' ),
                )
            ) . ';',
            'before'
        );

        wp_add_inline_script(
            'wcai-product-booking-calendar',
            $this->calendar_js_a() . "
" . $this->calendar_js_b() . "
" . $this->calendar_js_c()
        );
    }

